META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–4: ನಿಜವಾದ ಸಂನ್ಯಾಸಿ ಮತ್ತು ಯೋಗಿ ಯಾರು; 5–9: ನಿನ್ನನ್ನು ನೀನೇ ಉದ್ಧರಿಸಿಕೋ, ಮನಸ್ಸನ್ನು ಗೆದ್ದವನ ಸಮತ್ವ; 10–17: ಧ್ಯಾನದ ಪ್ರಾಯೋಗಿಕ ವಿಧಾನ ಮತ್ತು ಸಮತೋಲನದ ಜೀವನ; 18–32: ಧ್ಯಾನದಲ್ಲಿ ನೆಲೆಸಿದ ಮನಸ್ಸು, ಗಾಳಿಯಿಲ್ಲದ ಜಾಗದ ದೀಪದಂತೆ, ಎಲ್ಲರಲ್ಲೂ ಭಗವಂತನನ್ನು ಕಾಣುವುದು; 33–36: ಚಂಚಲ ಮನಸ್ಸನ್ನು ಅಭ್ಯಾಸ ಮತ್ತು ವೈರಾಗ್ಯದಿಂದ ಗೆಲ್ಲುವುದು; 37–47: ಯೋಗದಲ್ಲಿ ವಿಫಲನಾದವನ ಗತಿ, ಯಾವ ಪ್ರಯತ್ನವೂ ವ್ಯರ್ಥವಲ್ಲ, ಶ್ರೇಷ್ಠ ಯೋಗಿ.',
)
T = {
1: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಕರ್ಮಫಲವನ್ನು ಆಶ್ರಯಿಸದೆ ಮಾಡಬೇಕಾದ ಕರ್ಮವನ್ನು ಮಾಡುವವನೇ ಸಂನ್ಯಾಸಿ ಮತ್ತು ಯೋಗಿ; ಕೇವಲ ಅಗ್ನಿಯನ್ನು ಬಿಟ್ಟವನಲ್ಲ, ಕರ್ಮವನ್ನು ಬಿಟ್ಟವನಲ್ಲ.',
2: 'ಹೇ ಪಾಂಡವ, ಯಾವುದನ್ನು ಸಂನ್ಯಾಸ ಎನ್ನುತ್ತಾರೋ ಅದನ್ನೇ ಯೋಗ ಎಂದು ತಿಳಿ. ಸಂಕಲ್ಪಗಳನ್ನು (ಸ್ವಾರ್ಥದ ಬಯಕೆಗಳನ್ನು) ತ್ಯಜಿಸದೆ ಯಾರೂ ಯೋಗಿಯಾಗುವುದಿಲ್ಲ.',
3: 'ಯೋಗವನ್ನು ಏರಲು ಬಯಸುವ ಮುನಿಗೆ ಕರ್ಮವೇ ಸಾಧನ ಎನ್ನಲಾಗಿದೆ. ಯೋಗವನ್ನು ಏರಿದವನಿಗೆ ಶಾಂತಿಯೇ ಸಾಧನ ಎನ್ನಲಾಗಿದೆ.',
4: 'ಇಂದ್ರಿಯ ವಿಷಯಗಳಲ್ಲೂ ಕರ್ಮಗಳಲ್ಲೂ ಆಸಕ್ತನಾಗದೆ, ಎಲ್ಲ ಸಂಕಲ್ಪಗಳನ್ನೂ ತ್ಯಜಿಸಿದಾಗ ಅವನನ್ನು ಯೋಗಾರೂಢ ಎನ್ನುತ್ತಾರೆ.',
6: 'ಯಾರು ತನ್ನಿಂದಲೇ ತನ್ನನ್ನು ಗೆದ್ದಿದ್ದಾನೋ ಅವನಿಗೆ ತಾನೇ ತನ್ನ ಬಂಧು. ತನ್ನನ್ನು ಗೆಲ್ಲದವನಿಗೆ ತಾನೇ ಶತ್ರುವಿನಂತೆ ಶತ್ರುತ್ವದಲ್ಲಿ ವರ್ತಿಸುತ್ತಾನೆ.',
7: 'ತನ್ನನ್ನು ಗೆದ್ದ, ಶಾಂತನಾದವನ ಪರಮಾತ್ಮ ಚಳಿ-ಸೆಕೆ, ಸುಖ-ದುಃಖ, ಮಾನ-ಅಪಮಾನಗಳಲ್ಲಿ ಸ್ಥಿರವಾಗಿ ನೆಲೆಸಿರುತ್ತಾನೆ.',
8: 'ಜ್ಞಾನ ಮತ್ತು ವಿಜ್ಞಾನದಿಂದ ತೃಪ್ತನಾದ, ಅಚಲನಾದ, ಇಂದ್ರಿಯಗಳನ್ನು ಗೆದ್ದ, ಮಣ್ಣು, ಕಲ್ಲು ಮತ್ತು ಚಿನ್ನವನ್ನು ಸಮಾನವಾಗಿ ಕಾಣುವ ಯೋಗಿಯನ್ನು ಯುಕ್ತ ಎನ್ನುತ್ತಾರೆ.',
9: 'ಹಿತೈಷಿ, ಮಿತ್ರ, ಶತ್ರು, ಉದಾಸೀನ, ಮಧ್ಯಸ್ಥ, ದ್ವೇಷಿಸಬೇಕಾದವನು, ಬಂಧು, ಸಾಧು ಮತ್ತು ಪಾಪಿಗಳಲ್ಲೂ ಸಮಬುದ್ಧಿ ಇರುವವನು ವಿಶೇಷ ಶ್ರೇಷ್ಠ.',
10: 'ಯೋಗಿ ಏಕಾಂತ ಸ್ಥಳದಲ್ಲಿ ಒಬ್ಬನೇ ಇದ್ದು, ಮನಸ್ಸು ಮತ್ತು ದೇಹವನ್ನು ನಿಯಂತ್ರಿಸಿ, ಆಸೆಯಿಲ್ಲದೆ, ಸಂಗ್ರಹವಿಲ್ಲದೆ, ಸದಾ ತನ್ನನ್ನು ಯೋಗದಲ್ಲಿ ತೊಡಗಿಸಬೇಕು.',
11: 'ಶುದ್ಧ ಸ್ಥಳದಲ್ಲಿ, ಅತಿ ಎತ್ತರವೂ ಅತಿ ತಗ್ಗೂ ಅಲ್ಲದ, ದರ್ಭೆ, ಜಿಂಕೆಚರ್ಮ ಮತ್ತು ಬಟ್ಟೆಯನ್ನು ಒಂದರ ಮೇಲೊಂದು ಹಾಸಿದ ಸ್ಥಿರ ಆಸನವನ್ನು ಸ್ಥಾಪಿಸಿಕೊಂಡು,',
12: 'ಅಲ್ಲಿ ಆಸನದಲ್ಲಿ ಕುಳಿತು, ಮನಸ್ಸನ್ನು ಏಕಾಗ್ರಗೊಳಿಸಿ, ಚಿತ್ತ ಮತ್ತು ಇಂದ್ರಿಯಗಳ ಚಟುವಟಿಕೆಯನ್ನು ನಿಯಂತ್ರಿಸಿ, ಆತ್ಮಶುದ್ಧಿಗಾಗಿ ಯೋಗಾಭ್ಯಾಸ ಮಾಡಬೇಕು.',
13: 'ದೇಹ, ತಲೆ ಮತ್ತು ಕತ್ತನ್ನು ನೇರವಾಗಿ, ಅಲುಗಾಡದಂತೆ ಹಿಡಿದು, ಸ್ಥಿರವಾಗಿ, ತನ್ನ ಮೂಗಿನ ತುದಿಯನ್ನು ನೋಡುತ್ತಾ, ಬೇರೆ ದಿಕ್ಕುಗಳನ್ನು ನೋಡದೆ,',
14: 'ಪ್ರಶಾಂತ ಮನಸ್ಸಿನಿಂದ, ಭಯವಿಲ್ಲದೆ, ಬ್ರಹ್ಮಚರ್ಯ ವ್ರತದಲ್ಲಿ ನೆಲೆಸಿ, ಮನಸ್ಸನ್ನು ನಿಯಂತ್ರಿಸಿ, ನನ್ನಲ್ಲಿ ಚಿತ್ತವನ್ನಿಟ್ಟು, ನನ್ನನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಕುಳಿತುಕೊಳ್ಳಬೇಕು.',
15: 'ಹೀಗೆ ಸದಾ ತನ್ನನ್ನು ಯೋಗದಲ್ಲಿ ತೊಡಗಿಸುವ, ಮನಸ್ಸನ್ನು ನಿಯಂತ್ರಿಸಿದ ಯೋಗಿ ನನ್ನಲ್ಲಿ ನೆಲೆಸಿರುವ, ನಿರ್ವಾಣದಲ್ಲಿ ಕೊನೆಗೊಳ್ಳುವ ಶಾಂತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
16: 'ಹೇ ಅರ್ಜುನ, ಅತಿಯಾಗಿ ತಿನ್ನುವವನಿಗೂ, ಏನೂ ತಿನ್ನದವನಿಗೂ, ಅತಿಯಾಗಿ ನಿದ್ರಿಸುವವನಿಗೂ, ಸದಾ ಎಚ್ಚರವಾಗಿರುವವನಿಗೂ ಯೋಗ ಸಾಧ್ಯವಿಲ್ಲ.',
18: 'ಚೆನ್ನಾಗಿ ನಿಯಂತ್ರಿಸಿದ ಚಿತ್ತ ಆತ್ಮದಲ್ಲೇ ನೆಲೆಸಿದಾಗ, ಎಲ್ಲ ಕಾಮನೆಗಳಿಂದ ಆಸೆಯಿಲ್ಲದವನಾದಾಗ, ಅವನನ್ನು ಯುಕ್ತ ಎನ್ನುತ್ತಾರೆ.',
19: 'ಗಾಳಿಯಿಲ್ಲದ ಜಾಗದಲ್ಲಿ ದೀಪ ಅಲುಗಾಡದಂತೆ ಎಂಬ ಉಪಮೆ, ಆತ್ಮದ ಯೋಗದಲ್ಲಿ ತೊಡಗಿರುವ, ಚಿತ್ತವನ್ನು ನಿಯಂತ್ರಿಸಿದ ಯೋಗಿಗೆ ಹೇಳಲಾಗಿದೆ.',
20: 'ಯೋಗಾಭ್ಯಾಸದಿಂದ ನಿಗ್ರಹಿಸಲ್ಪಟ್ಟ ಚಿತ್ತ ಎಲ್ಲಿ ಶಾಂತವಾಗುತ್ತದೆಯೋ, ಎಲ್ಲಿ ತನ್ನಿಂದಲೇ ತನ್ನನ್ನು ಕಂಡು ತನ್ನಲ್ಲೇ ತೃಪ್ತನಾಗುತ್ತಾನೋ,',
21: 'ಬುದ್ಧಿಯಿಂದ ಗ್ರಹಿಸಬಲ್ಲ, ಇಂದ್ರಿಯಗಳನ್ನು ಮೀರಿದ ಆ ಅನಂತ ಸುಖವನ್ನು ಎಲ್ಲಿ ತಿಳಿಯುತ್ತಾನೋ, ಎಲ್ಲಿ ನೆಲೆಸಿ ತತ್ತ್ವದಿಂದ ಅಲುಗಾಡುವುದಿಲ್ಲವೋ,',
22: 'ಯಾವುದನ್ನು ಪಡೆದ ಮೇಲೆ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಲಾಭ ಬೇರೊಂದಿಲ್ಲ ಎಂದು ಭಾವಿಸುತ್ತಾನೋ, ಯಾವುದರಲ್ಲಿ ನೆಲೆಸಿದರೆ ದೊಡ್ಡ ದುಃಖವೂ ಅಲುಗಾಡಿಸಲಾರದೋ,',
23: 'ದುಃಖದ ಸಂಯೋಗದಿಂದ ವಿಯೋಗವೇ ಯೋಗ ಎಂದು ತಿಳಿ. ಆ ಯೋಗವನ್ನು ನಿಶ್ಚಯದಿಂದ, ಬೇಸರವಿಲ್ಲದ ಮನಸ್ಸಿನಿಂದ ಅಭ್ಯಾಸ ಮಾಡಬೇಕು.',
24: 'ಸಂಕಲ್ಪದಿಂದ ಹುಟ್ಟುವ ಎಲ್ಲ ಕಾಮನೆಗಳನ್ನೂ ಸಂಪೂರ್ಣವಾಗಿ ತ್ಯಜಿಸಿ, ಮನಸ್ಸಿನಿಂದಲೇ ಇಂದ್ರಿಯಗಳ ಗುಂಪನ್ನು ಎಲ್ಲ ಕಡೆಯಿಂದಲೂ ನಿಯಂತ್ರಿಸಿ,',
25: 'ಧೈರ್ಯದಿಂದ ಕೂಡಿದ ಬುದ್ಧಿಯಿಂದ ನಿಧಾನವಾಗಿ ನಿಧಾನವಾಗಿ ಶಾಂತನಾಗಬೇಕು. ಮನಸ್ಸನ್ನು ಆತ್ಮದಲ್ಲಿ ನೆಲೆಸಿ ಬೇರೇನನ್ನೂ ಚಿಂತಿಸಬಾರದು.',
26: 'ಚಂಚಲವೂ ಅಸ್ಥಿರವೂ ಆದ ಮನಸ್ಸು ಎಲ್ಲೆಲ್ಲಿಗೆ ಅಲೆಯುತ್ತದೆಯೋ, ಅಲ್ಲಲ್ಲಿಂದ ಅದನ್ನು ಹಿಂತೆಗೆದು ಆತ್ಮದ ವಶಕ್ಕೆ ತರಬೇಕು.',
27: 'ಮನಸ್ಸು ಪ್ರಶಾಂತವಾದ, ರಜೋಗುಣ ಶಮನವಾದ, ಪಾಪರಹಿತನಾದ, ಬ್ರಹ್ಮರೂಪನಾದ ಈ ಯೋಗಿಗೆ ಉತ್ತಮ ಸುಖ ಸಿಗುತ್ತದೆ.',
28: 'ಹೀಗೆ ಸದಾ ತನ್ನನ್ನು ಯೋಗದಲ್ಲಿ ತೊಡಗಿಸುವ ಪಾಪರಹಿತ ಯೋಗಿ ಸುಲಭವಾಗಿ ಬ್ರಹ್ಮಸಂಸ್ಪರ್ಶದ ಅನಂತ ಸುಖವನ್ನು ಅನುಭವಿಸುತ್ತಾನೆ.',
29: 'ಯೋಗದಲ್ಲಿ ತೊಡಗಿದ, ಎಲ್ಲೆಡೆ ಸಮದರ್ಶಿಯಾದವನು ಎಲ್ಲ ಜೀವಿಗಳಲ್ಲಿ ತನ್ನನ್ನೂ, ತನ್ನಲ್ಲಿ ಎಲ್ಲ ಜೀವಿಗಳನ್ನೂ ಕಾಣುತ್ತಾನೆ.',
30: 'ಯಾರು ನನ್ನನ್ನು ಎಲ್ಲೆಡೆಯೂ ಕಾಣುತ್ತಾನೋ, ಎಲ್ಲವನ್ನೂ ನನ್ನಲ್ಲಿ ಕಾಣುತ್ತಾನೋ, ಅವನಿಗೆ ನಾನು ಕಳೆದುಹೋಗುವುದಿಲ್ಲ, ಅವನು ನನಗೆ ಕಳೆದುಹೋಗುವುದಿಲ್ಲ.',
31: 'ಏಕತ್ವದಲ್ಲಿ ನೆಲೆಸಿ ಎಲ್ಲ ಜೀವಿಗಳಲ್ಲಿರುವ ನನ್ನನ್ನು ಭಜಿಸುವ ಯೋಗಿ, ಹೇಗೇ ಜೀವಿಸುತ್ತಿದ್ದರೂ ನನ್ನಲ್ಲೇ ಜೀವಿಸುತ್ತಾನೆ.',
32: 'ಹೇ ಅರ್ಜುನ, ತನ್ನೊಂದಿಗೆ ಹೋಲಿಸಿ ಎಲ್ಲೆಡೆ ಸಮವಾಗಿ ಕಾಣುವವನು, ಸುಖವಾಗಲಿ ದುಃಖವಾಗಲಿ, ಅವನೇ ಪರಮ ಯೋಗಿ ಎಂದು ಭಾವಿಸಲಾಗಿದೆ.',
33: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಮಧುಸೂದನ, ನೀವು ಸಮತ್ವದ ಈ ಯೋಗವನ್ನು ಹೇಳಿದಿರಿ, ಆದರೆ ಮನಸ್ಸಿನ ಚಂಚಲತೆಯಿಂದ ಅದರ ಸ್ಥಿರ ಸ್ಥಿತಿಯನ್ನು ನಾನು ಕಾಣುತ್ತಿಲ್ಲ.',
34: 'ಹೇ ಕೃಷ್ಣ, ಮನಸ್ಸು ಚಂಚಲ, ಕಳವಳ ಉಂಟುಮಾಡುವಂಥದ್ದು, ಬಲಿಷ್ಠ ಮತ್ತು ಹಠಮಾರಿ. ಅದನ್ನು ನಿಗ್ರಹಿಸುವುದು ಗಾಳಿಯನ್ನು ಹಿಡಿದಂತೆ ಬಹಳ ಕಷ್ಟ ಎಂದು ನನಗನಿಸುತ್ತದೆ.',
36: 'ಮನಸ್ಸನ್ನು ನಿಯಂತ್ರಿಸದವನಿಗೆ ಯೋಗ ಪಡೆಯುವುದು ಕಷ್ಟ ಎಂದು ನನ್ನ ಅಭಿಪ್ರಾಯ. ಆದರೆ ಮನಸ್ಸನ್ನು ವಶದಲ್ಲಿಟ್ಟುಕೊಂಡು ಪ್ರಯತ್ನಿಸುವವನು ಸರಿಯಾದ ಉಪಾಯದಿಂದ ಅದನ್ನು ಪಡೆಯಬಲ್ಲನು.',
37: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಕೃಷ್ಣ, ಶ್ರದ್ಧೆಯಿದ್ದರೂ ಪೂರ್ಣ ಪ್ರಯತ್ನ ಮಾಡದ, ಮನಸ್ಸು ಯೋಗದಿಂದ ಜಾರಿದ, ಯೋಗದ ಸಿದ್ಧಿಯನ್ನು ಪಡೆಯದವನಿಗೆ ಯಾವ ಗತಿ ಸಿಗುತ್ತದೆ?',
38: 'ಹೇ ಮಹಾಬಾಹು, ಎರಡರಿಂದಲೂ ಜಾರಿದ, ಆಶ್ರಯವಿಲ್ಲದ, ಬ್ರಹ್ಮಮಾರ್ಗದಲ್ಲಿ ದಾರಿ ತಪ್ಪಿದ ಅವನು ಹರಿದ ಮೋಡದಂತೆ ನಾಶವಾಗುವುದಿಲ್ಲವೇ?',
39: 'ಹೇ ಕೃಷ್ಣ, ನನ್ನ ಈ ಸಂಶಯವನ್ನು ನೀವು ಸಂಪೂರ್ಣವಾಗಿ ಕತ್ತರಿಸಬೇಕು. ನಿಮ್ಮ ಹೊರತು ಈ ಸಂಶಯವನ್ನು ಕತ್ತರಿಸಬಲ್ಲವರು ಬೇರೆ ಯಾರೂ ಇಲ್ಲ.',
40: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಪಾರ್ಥ, ಅವನಿಗೆ ಈ ಲೋಕದಲ್ಲಾಗಲಿ ಪರಲೋಕದಲ್ಲಾಗಲಿ ನಾಶವಿಲ್ಲ. ಹೇ ಮಗೂ, ಒಳ್ಳೆಯದನ್ನು ಮಾಡುವ ಯಾರೂ ದುರ್ಗತಿಗೆ ಹೋಗುವುದಿಲ್ಲ.',
41: 'ಯೋಗಭ್ರಷ್ಟನು ಪುಣ್ಯಾತ್ಮರ ಲೋಕಗಳನ್ನು ಪಡೆದು, ಅಲ್ಲಿ ಅನೇಕ ವರ್ಷಗಳು ವಾಸಿಸಿ, ಶುದ್ಧರೂ ಶ್ರೀಮಂತರೂ ಆದವರ ಮನೆಯಲ್ಲಿ ಹುಟ್ಟುತ್ತಾನೆ.',
42: 'ಅಥವಾ ಬುದ್ಧಿವಂತ ಯೋಗಿಗಳ ಕುಟುಂಬದಲ್ಲೇ ಹುಟ್ಟುತ್ತಾನೆ. ಇಂಥ ಜನ್ಮ ಈ ಲೋಕದಲ್ಲಿ ಸಿಗುವುದು ಬಹಳ ಅಪರೂಪ.',
43: 'ಹೇ ಕುರುನಂದನ, ಅಲ್ಲಿ ಅವನು ಹಿಂದಿನ ದೇಹದ ಬುದ್ಧಿಸಂಯೋಗವನ್ನು ಪಡೆಯುತ್ತಾನೆ, ಮತ್ತು ಅದರಿಂದ ಮತ್ತೆ ಸಿದ್ಧಿಗಾಗಿ ಇನ್ನೂ ಹೆಚ್ಚು ಪ್ರಯತ್ನಿಸುತ್ತಾನೆ.',
44: 'ಹಿಂದಿನ ಅಭ್ಯಾಸವೇ ಅವನನ್ನು ಅಸಹಾಯಕನಾಗಿ ಸೆಳೆಯುತ್ತದೆ. ಯೋಗವನ್ನು ತಿಳಿಯಲು ಬಯಸುವವನೂ ವೇದದ ಕರ್ಮಕಾಂಡವನ್ನು ಮೀರುತ್ತಾನೆ.',
45: 'ಆದರೆ ಪ್ರಯತ್ನದಿಂದ ಶ್ರಮಿಸುವ ಯೋಗಿ ಪಾಪಗಳಿಂದ ಶುದ್ಧನಾಗಿ, ಅನೇಕ ಜನ್ಮಗಳಲ್ಲಿ ಸಿದ್ಧಿಯನ್ನು ಪಡೆದು, ನಂತರ ಪರಮ ಗತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
46: 'ಯೋಗಿ ತಪಸ್ವಿಗಳಿಗಿಂತ ಶ್ರೇಷ್ಠ, ಜ್ಞಾನಿಗಳಿಗಿಂತಲೂ ಶ್ರೇಷ್ಠ ಎಂದು ಭಾವಿಸಲಾಗಿದೆ, ಕರ್ಮಿಗಳಿಗಿಂತಲೂ ಯೋಗಿ ಶ್ರೇಷ್ಠ. ಆದ್ದರಿಂದ ಹೇ ಅರ್ಜುನ, ಯೋಗಿಯಾಗು.',
47: 'ಎಲ್ಲ ಯೋಗಿಗಳಲ್ಲೂ, ಯಾರು ಶ್ರದ್ಧೆಯಿಂದ ತನ್ನ ಅಂತರಂಗವನ್ನು ನನ್ನಲ್ಲಿ ತೊಡಗಿಸಿ ನನ್ನನ್ನು ಭಜಿಸುತ್ತಾನೋ, ಅವನನ್ನು ನಾನು ಅತ್ಯಂತ ಶ್ರೇಷ್ಠ ಯೋಗಿ ಎಂದು ಭಾವಿಸುತ್ತೇನೆ.',
}
